import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    degrees = [0] * n
    xors = [0] * n

    for i in range(n):
        degrees[i] = int(next(iterator))
        xors[i] = int(next(iterator))

    q = deque()
    for i in range(n):
        if degrees[i] == 1:
            q.append(i)

    edges = []

    while q:
        u = q.popleft()
        if degrees[u] == 0:
            continue

        v = xors[u]
        edges.append((u, v))

        degrees[v] -= 1
        xors[v] ^= u

        if degrees[v] == 1:
            q.append(v)

        degrees[u] = 0

    print(len(edges))
    for a, b in edges:
        print(f"{a} {b}")

if __name__ == "__main__":
    main()
